# Example values to try:
#   0.10, 0.25, 0.50, 1.00
COLOCALIZATION_DISTANCE_UM = 0.25

# Coordinate scale factors.
# If your converted_coordinates files are already in microns, keep these at 1.
A_X_SCALE_UM = 1.0
A_Y_SCALE_UM = 1.0
A_Z_SCALE_UM = 1.0

B_X_SCALE_UM = 1.0
B_Y_SCALE_UM = 1.0
B_Z_SCALE_UM = 1.0

# Only use files inside converted_coordinates folders.
# This avoids accidentally analyzing derived surface-distance tables or summaries.
PROCESS_ONLY_CONVERTED_COORDINATES = True

# Make per-cell plots. Turn off if the run is very large and you only want tables.
